import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Box,
  CircularProgress,
  Paper,
  IconButton,
  Snackbar,
  Alert
} from '@mui/material';
import { Close as CloseIcon } from '@mui/icons-material';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000';

export default function DocuSignModal({ open, onClose, onSigningComplete, formData }) {
  const [isLoading, setIsLoading] = useState(true);
  const [isSigning, setIsSigning] = useState(false);
  const [error, setError] = useState(null);
  const [envelopeId, setEnvelopeId] = useState('');
  const [signingUrl, setSigningUrl] = useState('');
  const [showSuccess, setShowSuccess] = useState(false);

  useEffect(() => {
    let isMounted = true;

    const createEnvelope = async () => {
      if (!open) return;

      try {
        setIsLoading(true);
        setError(null);

        const response = await fetch(`${API_BASE_URL}/api/docusign/envelope`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            signer: {
              email: formData.email,
              name: `${formData.firstName} ${formData.lastName}`,
              client_user_id: formData.email
            },
            return_url: `${window.location.origin}/appointments`
          })
        });

        if (!response.ok) {
          throw new Error('Failed to create signing session');
        }

        const data = await response.json();

        if (isMounted) {
          setEnvelopeId(data.envelope_id);
          setSigningUrl(data.redirect_url);
        }
      } catch (err) {
        console.error('DocuSign Error:', err);
        if (isMounted) {
          setError('Failed to prepare document for signing. Please try again.');
        }
      } finally {
        if (isMounted) {
          setIsLoading(false);
        }
      }
    };

    if (open) {
      createEnvelope();
    }

    return () => {
      isMounted = false;
    };
  }, [open, formData]);

  const handleSigningComplete = () => {
    setShowSuccess(true);
    onSigningComplete();
  };

  const handleCloseSuccess = () => {
    setShowSuccess(false);
    onClose();
  };

  const handleSignDocument = () => {
    if (!signingUrl) return;

    setIsSigning(true);
    const newWindow = window.open(signingUrl, '_blank', 'noopener,noreferrer');

    if (newWindow) {
      // Check if the document was signed every 5 seconds
      const checkStatus = setInterval(async () => {
        try {
          // In a real app, you would check the envelope status via webhook or API
          // For now, we'll just wait for the user to return to the app
          if (newWindow.closed) {
            clearInterval(checkStatus);
            handleSigningComplete();
          }
        } catch (err) {
          console.error('Error checking signing status:', err);
          clearInterval(checkStatus);
        }
      }, 5000);
    } else {
      setError('Please allow popups for this website to sign the document.');
      setIsSigning(false);
    }
  };

  if (!open) return null;

  return (
    <Dialog 
      open={open} 
      onClose={onClose}
      maxWidth="md"
      fullWidth
    >
      <DialogTitle>
        <Box display="flex" justifyContent="space-between" alignItems="center">
          <Typography variant="h6">Sign Service Agreement</Typography>
          <IconButton onClick={onClose} size="small">
            <CloseIcon />
          </IconButton>
        </Box>
      </DialogTitle>
      <DialogContent>
        {isLoading ? (
          <Box display="flex" justifyContent="center" my={4}>
            <CircularProgress />
            <Typography variant="body1" ml={2}>
              Preparing your document for signing...
            </Typography>
          </Box>
        ) : error ? (
          <Box textAlign="center" my={4}>
            <Typography color="error">{error}</Typography>
            <Button 
              variant="contained" 
              color="primary" 
              onClick={() => window.location.reload()}
              sx={{ mt: 2 }}
            >
              Try Again
            </Button>
          </Box>
        ) : (
          <Box>
            <Paper elevation={3} sx={{ p: 2, mb: 3 }}>
              <Typography variant="h6" gutterBottom>
                Service Agreement
              </Typography>
              <Typography paragraph>
                Please review and sign the service agreement to proceed with your appointment.
              </Typography>
              <Typography variant="body2" color="textSecondary">
                By signing, you agree to our terms of service and privacy policy.
              </Typography>
            </Paper>

            <Box textAlign="center" my={3}>
              <Button
                variant="contained"
                color="primary"
                size="large"
                onClick={handleSignDocument}
                disabled={isSigning}
                startIcon={isSigning ? <CircularProgress size={20} color="inherit" /> : null}
                sx={{ minWidth: 200 }}
              >
                {isSigning ? 'Opening Signing...' : 'Sign Document'}
              </Button>
            </Box>
          </Box>
        )}
      </DialogContent>
      <DialogActions sx={{ p: 2 }}>
        <Button 
          onClick={onClose} 
          disabled={isLoading || isSigning}
          color="inherit"
        >
          {isSigning ? 'Signing in progress...' : 'Cancel'}
        </Button>
        {!isLoading && !error && !isSigning && (
          <Button
            variant="contained"
            color="primary"
            onClick={handleSignDocument}
            disabled={!signingUrl}
          >
            Open Signing
          </Button>
        )}
      </DialogActions>

      <Snackbar
        open={showSuccess}
        autoHideDuration={6000}
        onClose={handleCloseSuccess}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert onClose={handleCloseSuccess} severity="success" sx={{ width: '100%' }}>
          Document signed successfully!
        </Alert>
      </Snackbar>
    </Dialog>
  );
}
